import cv2, numpy as np
im=cv2.imread('first_frame.png')[:,:,::-1]
hsv=cv2.cvtColor(im,cv2.COLOR_RGB2HSV)
conds={
'hueyellow':(hsv[:,:,0]>15)&(hsv[:,:,0]<45)&(hsv[:,:,1]>50),
'olive':(im[:,:,0]>im[:,:,2]*1.5)&(im[:,:,1]>im[:,:,2]*1.35)&(im[:,:,0]>40),
'brightwarm':(im[:,:,0]>100)&(im[:,:,1]>70)&(im[:,:,0]-im[:,:,2]>30),
'dark':im.mean(2)<45,
'bright':im.mean(2)>210,
}
for name,m in conds.items():
 print('\\n',name, m.sum())
 n,la,st,ce=cv2.connectedComponentsWithStats(m.astype('uint8'),8)
 for j in np.argsort(st[1:,4])[-20:][::-1]+1:
  x,y,w,h,a=st[j];
  if a>=2: print(a,(x,y,w,h),tuple(np.round(ce[j],1)))
# detailed pixel crop for yellow likely top at x50:105 y5:30 print rgb/hsv high sat points
print('\\nTop high saturation points')
for y in range(0,35):
 z=[]
 for x in range(30,110):
  r,g,b=map(int,im[y,x]);
  if max(r,g,b)-min(r,g,b)>40 and r>g and g>b: z.append((x,(r,g,b)))
 if z: print(y,z)
PY"
